contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, string calldata description) public payable {
        require(caller != address(0), "caller must be nonzero");
        bool isTeam = (caller == c.jojoTeam());
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert((caller == c.jojoTeam()) == !reverted || !isTeam && reverted);
    }
}
